head.script:
scwin.gVar = {
    "cID" : "target1"
}



scwin.onpageload = function () {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }

    // 조건 설정 (con_ID 입력값 → 빈 값이면 내부 규칙에 의한 ID 부여)
    let cID = scwin.gVar["cID"];

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();

    // slideHide 컨테이너 생성 (자식 없이) — inline 자식은 재생성 시 미파싱되므로 .main 에 개별 생성
    let strTarget = '';
    strTarget += '<w2:slideHide ' + strNameSpace + ' firstStatus="slide" showSize="15" slideDirection="left" style="position:relative;width:95px;height:182px;">';
    strTarget += '</w2:slideHide>';

    scwin.target1 = await $p.dynamicCreate(
        cID,
        "slideHide",
        strTarget,
        grp_comp
    );

    // slideHideMain(.main) 안에 자식 개별 생성
    let mainEl = scwin.target1.main;
    let strBar = '<xf:group ' + strNameSpace + ' ev:onclick="fn_slideHide" id="" style="position:absolute;left:0px;height:100%;width:15px;background-color:#bbb;"></xf:group>';
    await $p.dynamicCreate('', 'group', strBar, mainEl);
    let strTxt1 = '<w2:textbox ' + strNameSpace + ' id="" label="Favorite" style="padding:10px 4px;margin-left:15px;color:#bbb;font-weight:bold;background-color:#fff;border-bottom:4px double #ccc;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTxt1, mainEl);
    let strTxt2 = '<w2:textbox ' + strNameSpace + ' id="" label="- Fruits" style="padding:6px 4px;margin-left:15px;color:#bbb;font-weight:bold;background-color:#fff;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTxt2, mainEl);
    let strTxt3 = '<w2:textbox ' + strNameSpace + ' id="" label="- Fish" style="padding:6px 4px;margin-left:15px;color:#bbb;font-weight:bold;background-color:#fff;"></w2:textbox>';
    await $p.dynamicCreate('', 'textbox', strTxt3, mainEl);

    // 토글 핸들러 (실제 slide 상태 isOpen 기준)
    fn_slideHide = function (e) {
        if (scwin.target1.isOpen()) {
            scwin.target1.startHide();
        } else {
            scwin.target1.startSlide();
        }
    };
}
